import{z as d,x as i,o as r,c as p,q as t,j as n,D as E,d as e,s,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"ORM 阻抗失配","description":"","frontmatter":{"title":"ORM 阻抗失配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orm-impedance.md","filePath":"cs/orm-impedance.md","lastUpdated":1791413859000}'),B={name:"cs/orm-impedance.md"};function m(c,a,D,h,u,f){const o=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="orm-阻抗失配" tabindex="-1">ORM 阻抗失配 <a class="header-anchor" href="#orm-阻抗失配" aria-label="Permalink to &quot;ORM 阻抗失配&quot;">​</a></h1><div class="epigraph"><p>对象图有身份、继承与导航；关系有键、表与声明查询。把前者硬按进后者，不是翻译错误，是两种模型的阻抗。</p><footer>—— 据 Copeland and Maier 对对象–关系；Ireland et al. 对阻抗失配；Date 对关系与对象对照</footer></div><p><a href="/cs/schema-migration">上一课</a>把模式当版本化脚本。本课不重写 <code>ALTER</code>。缺口是应用层：对象关系映射（ORM）用类表示元组，用导航表示连接。主干坚持声明 SQL；工程上大量代码通过 ORM 发查询。阻抗失配（impedance mismatch）命名这条缝，避免把 N+1 查询当成「数据库慢」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对象：可变身份、嵌套集合、继承。关系：值、第一范式、集合查询。映射策略：一类一表、一类一层次一张表、具体类一表——各有空列或连接代价。缺口不是选框架，而是<strong>查询形状</strong>：按对象导航 <code>customer.orders</code> 若逐订单懒加载，就是对每个外键一次查询（N+1）。关系侧一句话连接能做完的，对象侧循环会拆碎。</p><p><span class="marginnote">直觉类比：阻抗失配像把一篇散文逐句填进表格——句子（对象）有指代（身份）和嵌套从句（图导航），表格（关系）只认行列与外键；怎么填都别扭，不是某句写错了，是两种容器的形状不同。</span></p><p>单元工作（Unit of Work）跟踪脏对象再生成 <code>UPDATE</code>，与保存点、事务边界必须对齐。迁移工具从实体生成 DDL，常忽略 <a href="/cs/normal-forms">依赖理论</a> 的分解质量。</p><p><span class="marginnote">Copeland and Maier 讨论把对象存进关系。阻抗一词借自电路：两种接口能量反射。本课不把 NoSQL 文档当「阻抗消失」——嵌套文档只是把连接预物化，下一课连接池也不解决模型缝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>显式查询：把需要的图写成一次 JOIN 或窗口，而不是默认懒加载。投影：不要 <code>SELECT *</code> 水合整个对象图。身份映射：同一主键在同一会话不要两份对象。继承映射写进模式，让迁移课的脚本可见，而不是只在注解里。</p><p>ORM 可以发出参数化 SQL，进入后课预编译。它也可以把过程与触发器完全藏起来——调试时必须能看到最终 SQL。</p>',11)),(r(),n(l,null,{default:E(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%E5%9B%BE%E5%AF%BC%E8%88%AA%22%5D%20--%3E%20N1%5B%22N%2B1%20%E6%AC%A1%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20REL%5B%22%E5%A3%B0%E6%98%8E%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E8%AE%A1%E5%88%92%22%5D%0A%20%20MAP%5B%22%E6%98%A0%E5%B0%84%E7%AD%96%E7%95%A5%22%5D%20--%3E%20SCH%5B%22%E8%A1%A8%20%2F%20%E5%88%97%20%2F%20%E7%A9%BA%E5%88%97%22%5D%0A%20%20UOW%5B%22%E5%8D%95%E5%85%83%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20TX%5B%22%E5%90%8C%E4%B8%80%E4%BA%8B%E5%8A%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[e("延迟加载与事务：会话关闭后再导航，连接可能已还，对象成「断开」。这与库的隔离快照不是同一层。脏检查生成的 "),A("code",null,"UPDATE"),e(" 可能覆盖列，与触发器、乐观版本列互相踩。约束仍在库侧生效；ORM 校验只是提前失败，不是完整性来源。")],-1)),(r(),n(l,null,{default:E(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIST%5B%22%E4%B8%80%E6%AC%A1%E6%9F%A5%E5%87%BA%20100%20%E4%B8%AA%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20NAV%5B%22%E4%BB%A3%E7%A0%81%E8%AE%BF%E9%97%AE%20customer.orders%22%5D%0A%20%20NAV%20--%3E%20LOADED%7B%22%E8%AE%A2%E5%8D%95%E5%B7%B2%E9%9A%8F%E8%A1%8C%E5%8A%A0%E8%BD%BD%3F%22%7D%0A%20%20LOADED%20--%3E%7C%22%E5%90%A6%2C%20%E6%87%92%E5%8A%A0%E8%BD%BD%22%7C%20LOOP%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%E5%AE%A2%E6%88%B7%E5%86%8D%E5%8F%91%E4%B8%80%E6%9D%A1%E8%AE%A2%E5%8D%95%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20LOOP%20--%3E%20TOTAL%5B%22%E5%90%88%E8%AE%A1%20101%20%E6%9D%A1%E6%9F%A5%E8%AF%A2%3A%201%20%E5%8A%A0%20N%22%5D%0A%20%20LOADED%20--%3E%7C%22%E6%98%AF%2C%20JOIN%20%E9%A2%84%E5%8F%96%22%7C%20ONE%5B%22%E4%B8%80%E6%AC%A1%E5%8F%96%E5%9B%9E%2C%20%E5%90%88%E8%AE%A1%201%20%E6%9D%A1%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：页面要展示 100 个客户各自的订单。导航式懒加载发 1 条客户查询、再 100 条订单查询，共 101 次往返；改成一条 JOIN 或一次 IN 预取只要 1 次往返——若每次往返 1 毫秒，仅等待就差了两个数量级，「数据库慢」常常是这条缝。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲连接池尺寸公式——下一课。也不把活动记录对仓库模式的宗教争论写入主干。文档库、宽列是后课数据模型族；它们不自动消除图与集合的缝，只是换一种预连接。</p><p>后课默认：对象导航不是查询计划。看到 N+1 先改加载形状，再谈索引。连接池处理的是会话资源，不是阻抗。</p><p>关系查询的单位是语句与计划；对象的单位是身份与指针。翻译层必须显式。</p><p><span class="marginnote">常见误区：初学者容易把 ORM 的字段校验当成数据完整性的来源。唯一键、外键、检查约束只在数据库侧真正生效——绕过应用的写入、并发的另一方，ORM 校验都拦不住；校验只是「提前失败」，完整性合同仍在库里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阻抗来自对象图对关系的结构差，不是某框架的 bug。</li><li>N+1 是导航默认值；声明连接才是原语。</li><li>连接池下一课：会话昂贵，与映射无关却总被混谈。</li><li>出处：Copeland and Maier；Ireland 等；Date。</li></ul>',8))])}const _=d(B,[["render",m]]);export{O as __pageData,_ as default};
